rules.css:
.kb-modal {
  width: min(94vw, 780px);
  max-width: 780px;
  max-height: min(92vh, 920px);
  padding: 0;
  background: var(--bg-secondary);
  box-shadow: var(--shadow-lg);
}

.kb-intro,
.kb-section {
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--bg-card);
}

.kb-intro {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 16px 18px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--accent) 8%, transparent), transparent 58%),
    var(--bg-card);
}

.kb-intro-copy > strong {
  display: block;
  color: var(--text-primary);
  font-size: 14px;
  line-height: 1.4;
}

.kb-intro-copy p,
.kb-section-head p,
.kb-field-help {
  margin: 4px 0 0;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.5;
}

.kb-intro a,
.kb-section a,
.kb-setup-details a {
  color: var(--accent);
  text-decoration: none;
}

.kb-status {
  flex: 0 0 auto;
  max-width: 230px;
  padding: 7px 10px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: color-mix(in srgb, var(--bg-secondary) 88%, transparent);
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.35;
  text-align: right;
}

.kb-status-detail {
  max-width: 210px;
  margin-top: 3px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.kb-section-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 12px;
}

.kb-section-head h3 {
  margin: 0;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 13px;
  font-weight: 650;
  letter-spacing: 0;
}

.kb-enable-control {
  display: flex;
  align-items: center;
  gap: 9px;
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
}

.kb-field-control {
  box-sizing: border-box;
  width: 100%;
  min-height: 40px;
  padding: 9px 11px;
  border: 1px solid var(--border);
  border-radius: 9px;
  outline: none;
  background: var(--select-surface);
  color: var(--text-primary);
  font: inherit;
  font-size: 13px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}

select.kb-field-control {
  appearance: none;
  -webkit-appearance: none;
  padding-right: 34px;
  cursor: pointer;
  background-image:
    linear-gradient(45deg, transparent 50%, var(--text-muted) 50%),
    linear-gradient(135deg, var(--text-muted) 50%, transparent 50%);
  background-position: calc(100% - 17px) 50%, calc(100% - 12px) 50%;
  background-repeat: no-repeat;
  background-size: 5px 5px, 5px 5px;
}

.kb-text-btn {
  min-height: 32px;
  padding: 5px 8px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
}

.kb-text-btn:hover,
.kb-text-btn:focus-visible {
  background: var(--bg-hover);
  color: var(--text-primary);
  outline: none;
}

.kb-text-btn-danger:hover,
.kb-text-btn-danger:focus-visible {
  background: color-mix(in srgb, var(--red) 10%, transparent);
  color: var(--red);
}

.kb-stats {
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--border) 75%, transparent);
  border-radius: 10px;
  background: color-mix(in srgb, var(--bg-secondary) 80%, transparent);
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.5;
}

.kb-stats-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 7px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--green) 12%, transparent);
}

.kb-performance-note {
  margin-top: 7px;
  padding-top: 7px;
  border-top: 1px dashed var(--border);
  color: color-mix(in srgb, #fbbf24 72%, var(--text-muted));
  line-height: 1.45;
}

.kb-drop-zone {
  display: flex;
  min-height: 92px;
  margin-top: 10px;
  padding: 14px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 4px;
  border: 1.5px dashed color-mix(in srgb, var(--border) 84%, var(--text-muted));
  border-radius: 12px;
  background: color-mix(in srgb, var(--bg-secondary) 56%, transparent);
  color: var(--text-muted);
  font-size: 11px;
  text-align: center;
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease, color 0.15s ease;
}

.kb-drop-zone:hover,
.kb-drop-zone:focus-visible,
.kb-drop-zone.is-dragging {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 7%, var(--bg-card));
  color: var(--text-secondary);
  outline: none;
}

.kb-inline-progress progress,
.kb-ingest-pill progress {
  width: 100%;
  height: 6px;
  accent-color: var(--accent);
}

.kb-document-table {
  max-height: 220px;
  overflow-y: auto;
  border: 1px solid var(--border);
  border-radius: 10px;
}

.kb-document-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 9px;
  min-height: 38px;
  padding: 5px 8px 5px 11px;
  color: var(--text-secondary);
  font-size: 11px;
}

.kb-document-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.kb-doc-delete {
  display: inline-flex;
  width: 26px;
  height: 26px;
  padding: 0;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--text-muted);
  font-size: 16px;
  cursor: pointer;
}

.kb-doc-delete:hover,
.kb-doc-delete:focus-visible {
  background: color-mix(in srgb, var(--red) 10%, transparent);
  color: var(--red);
  outline: none;
}

.kb-retrieval-grid {
  display: grid;
  grid-template-columns: minmax(150px, 0.55fr) minmax(240px, 1.45fr);
  gap: 12px;
  align-items: stretch;
}

.kb-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 6px;
}

.kb-field > span,
.kb-compact-field > span {
  color: var(--text-primary);
  font-size: 11px;
  font-weight: 600;
}

.kb-field small,
.kb-option-card small {
  display: block;
  color: var(--text-muted);
  font-size: 10px;
  line-height: 1.45;
}

.kb-option-card {
  display: flex;
  min-width: 0;
  gap: 9px;
  padding: 11px 12px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: color-mix(in srgb, var(--bg-secondary) 72%, transparent);
  cursor: pointer;
}

.kb-option-card strong {
  display: block;
  margin-bottom: 3px;
  color: var(--text-primary);
  font-size: 11px;
}

.kb-field-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 14px;
}

.kb-setup-details {
  border: 1px solid var(--border);
  border-radius: 10px;
  background: color-mix(in srgb, var(--bg-secondary) 76%, transparent);
  color: var(--text-muted);
  font-size: 11px;
}

.kb-setup-details summary {
  padding: 10px 12px;
  color: var(--text-primary);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
}

.kb-command {
  display: block;
  padding: 8px 10px;
  overflow-wrap: anywhere;
  border-radius: 7px;
  background: var(--bg-primary);
  color: var(--text-primary);
  font-family: var(--font-mono, monospace);
}

.kb-footer-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding-top: 2px;
}

.kb-privacy-note {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--accent) 5%, var(--bg-card));
  color: var(--text-muted);
  font-size: 10px;
  line-height: 1.5;
}

.kb-create-dialog {
  width: min(100%, 600px);
  max-height: min(90vh, 760px);
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--bg-secondary);
  box-shadow: var(--shadow-lg);
}

.kb-create-device {
  margin-bottom: 14px;
  padding: 9px 11px;
  border-radius: 9px;
  background: color-mix(in srgb, var(--accent) 6%, var(--bg-card));
  color: var(--text-muted);
  font-size: 10px;
  line-height: 1.45;
}

.kb-model-card {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: start;
  padding: 11px 12px;
  border: 1px solid var(--border);
  border-radius: 11px;
  background: var(--bg-card);
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}

.kb-model-card:has(input:checked) {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 6%, var(--bg-card));
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent) 13%, transparent);
}

.kb-model-title {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 650;
}

.kb-model-profile {
  color: var(--accent);
  font-family: var(--font-mono, monospace);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.kb-recommended-badge {
  padding: 3px 6px;
  border-radius: 999px;
  background: var(--accent);
  color: #fff;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: nowrap;
}

.kb-create-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px solid var(--border);
}

.kb-ingest-pill {
  position: fixed;
  right: 20px;
  bottom: 88px;
  z-index: 9999;
  width: min(330px, calc(100vw - 32px));
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg-secondary);
  box-shadow: var(--shadow-lg);
  color: var(--text-primary);
  font-size: 11px;
}

.kb-ingest-pill-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 7px;
}

.kb-ingest-pill-head strong {
  color: var(--text-muted);
  font-size: 9px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.kb-ingest-pill-dismiss {
  padding: 0 4px;
  border: 0;
  background: transparent;
  color: var(--text-muted);
  font-size: 16px;
  cursor: pointer;
}

.kb-ingest-pill-text {
  margin-bottom: 8px;
  overflow: hidden;
  color: var(--text-secondary);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.kb-ingest-pill-stop {
  width: 100%;
  margin-top: 7px;
  padding: 6px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: transparent;
  color: var(--text-secondary);
  font: inherit;
  font-size: 10px;
  cursor: pointer;
}

.kb-doc-delete {
  flex-shrink: 0;
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
  padding: 0 6px;
  border-radius: 4px;
  transition: color 0.15s, background 0.15s;
}
